// Use Rhino 1.9.0 features: https://mozilla.github.io/rhino/compat/engines.html
(function () {
  function hex(bytes) {
    var out = "";
    for (var i = 0; i < bytes.length; i++) {
      var value = bytes[i];
      if (value < 0) {
        value += 256;
      }
      out += ("0" + value.toString(16)).slice(-2);
    }
    return out;
  }

  return {
    run: function (ctx, node) {
      var props = ctx.props(node);
      var text = String(ctx.template(props.text || ""));
      var digest = Packages.java.security.MessageDigest.getInstance("SHA-256");
      var bytes = digest.digest(new java.lang.String(text).getBytes("UTF-8"));
      return {
        algorithm: "SHA-256",
        input: text,
        digest: hex(bytes)
      };
    }
  };
}())

function sample_list_filter_sort_map({ input, config, result }) {
  var cities = [{"city":"Lyon","temperature":31},{"city":"Paris","temperature":38},{"city":"Marseille","temperature":36}]
  var hotCities = list.filter({ id: "keepHotCities", items: cities, where: current.temperature >= 35 })
  var sortedHotCities = list.sort({ id: "sortByCity", items: hotCities, by: current.city })
  list.map({ id: "names", items: sortedHotCities, select: current.city, out: "result.cities" })
  result.count = result.cities.length
  return result
}

function sample_json_object_output({ input, config, result }) {
  var news = {"title":"Flow samples are executable","count":3}
  json.object({ id: "response", out: "result.payload" }) {
    json.field({ id: "title", key: "title", value: news.title })
    json.field({ id: "count", key: "count", value: news.count })
    json.field({ id: "status", key: "status", value: "ok" })
  }
  return result
}

